    if dy > 0: dy *= 1 + (F('bk', 1.0) - 1) * float(np.clip((ZTOP - 0.02 - zn) / 0.12, 0, 1)) ** 2 * (3 - 2 * float(np.clip((ZTOP - 0.02 - zn) / 0.12, 0, 1)))   # back-only depth (bustle)
